1	import React from "react";
2	import { type LucideIcon } from "lucide-react";
3	import { Button } from "@/components/ui/button";
4	import { Link } from "react-router-dom";
5	import { cn } from "@/lib/utils";
6	
7	interface EmptyStateProps {
8	  icon: LucideIcon;
9	  title: string;
10	  description: string;
11	  actionLabel?: string;
12	  actionHref?: string;
13	  onAction?: () => void;
14	  className?: string;
15	}
16	
17	export const EmptyState = React.forwardRef<HTMLDivElement, EmptyStateProps>(function EmptyState({
18	  icon: Icon,
19	  title,
20	  description,
21	  actionLabel,
22	  actionHref,
23	  onAction,
24	  className,
25	}, ref) {
26	  return (
27	    <div ref={ref} className={cn("flex flex-col items-center justify-center py-16 text-center", className)}>
28	      <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-2xl border border-border/40 bg-muted/40">
29	        <Icon className="h-7 w-7 text-muted-foreground" />
30	      </div>
31	      <h3 className="text-lg font-semibold text-foreground">{title}</h3>
32	      <p className="mt-1.5 max-w-sm text-sm text-muted-foreground">{description}</p>
33	      {actionLabel && (
34	        actionHref ? (
35	          <Button asChild className="mt-5" size="sm">
36	            <Link to={actionHref}>{actionLabel}</Link>
37	          </Button>
38	        ) : (
39	          <Button className="mt-5" size="sm" onClick={onAction}>{actionLabel}</Button>
40	        )
41	      )}
42	    </div>
43	  );
44	});
