1	import { useState, useMemo } from "react";
2	import { Link, useNavigate } from "react-router-dom";
3	import {
4	  Search,
5	  ScanLine,
6	  MoreVertical,
7	  Eye,
8	  RefreshCw,
9	  Trash2,
10	  Globe,
11	  Bell,
12	  BellOff,
13	  X,
14	} from "lucide-react";
15	import { Card, CardContent } from "@/components/ui/card";
16	import { Button } from "@/components/ui/button";
17	import { Input } from "@/components/ui/input";
18	import { Badge } from "@/components/ui/badge";
19	import { Skeleton } from "@/components/ui/skeleton";
20	import {
21	  Table,
22	  TableBody,
23	  TableCell,
24	  TableHead,
25	  TableHeader,
26	  TableRow,
27	} from "@/components/ui/table";
28	import {
29	  Select,
30	  SelectContent,
31	  SelectItem,
32	  SelectTrigger,
33	  SelectValue,
34	} from "@/components/ui/select";
35	import {
36	  DropdownMenu,
37	  DropdownMenuContent,
38	  DropdownMenuItem,
39	  DropdownMenuSeparator,
40	  DropdownMenuTrigger,
41	} from "@/components/ui/dropdown-menu";
42	import { PageHeader } from "@/components/shared/PageHeader";
43	import { ScoreRing } from "@/components/shared/ScoreRing";
44	import { EmptyState } from "@/components/shared/EmptyState";
45	import { PageTransition } from "@/components/shared/PageTransition";
46	import { getScoreLabel, getScoreColor } from "@/lib/score-utils";
47	import { useScans, useDeleteScan } from "@/hooks/use-scans";
48	import { useMonitoring } from "@/hooks/use-monitoring";
49	import { useAuth } from "@/contexts/AuthContext";
50	import { toast } from "sonner";
51	import { cn } from "@/lib/utils";
52	
53	function formatDate(dateStr: string) {
54	  return new Date(dateStr).toLocaleDateString("en-US", {
55	    month: "short",
56	    day: "numeric",
57	    year: "numeric",
58	  });
59	}
60	
61	// ── Loading skeleton ────────────────────────────────────────────
62	
63	function ReportTableSkeleton() {
64	  return (
65	    <Card className="border-border/40 shadow-soft overflow-hidden">
66	      <div className="p-0">
67	        <div className="border-b bg-muted/20 px-4 py-3">
68	          <div className="flex gap-8">
69	            {[120, 60, 50, 60, 60, 70, 30].map((w, i) => (
70	              <Skeleton key={i} className="h-4" style={{ width: w }} />
71	            ))}
72	          </div>
73	        </div>
74	        {[1, 2, 3, 4, 5].map((i) => (
75	          <div key={i} className="flex items-center gap-8 border-b border-border/30 px-4 py-4">
76	            <div className="flex items-center gap-3">
77	              <Skeleton className="h-9 w-9 rounded-lg" />
78	              <div className="space-y-1.5">
79	                <Skeleton className="h-4 w-36" />
80	                <Skeleton className="h-3 w-24" />
81	              </div>
82	            </div>
83	            <Skeleton className="h-7 w-7 rounded-full" />
84	            <Skeleton className="h-4 w-12" />
85	            <Skeleton className="h-5 w-16 rounded-full" />
86	            <Skeleton className="h-5 w-20 rounded-full" />
87	            <Skeleton className="h-4 w-20" />
88	            <Skeleton className="h-8 w-8 rounded-lg" />
89	          </div>
90	        ))}
91	      </div>
92	    </Card>
93	  );
94	}
95	
96	// ── Status badge ───────────────────────────────────────────────
97	
98	function getStatusBadge(status: string) {
99	  if (status === "completed") {
100	    return (
101	      <Badge variant="outline" className="border-emerald-200/80 bg-emerald-50/50 text-emerald-700 text-xs">
102	        Completed
103	      </Badge>
104	    );
105	  }
106	  if (status === "analyzing") {
107	    return (
108	      <Badge variant="outline" className="border-amber-200/80 bg-amber-50/50 text-amber-700 text-xs animate-pulse">
109	        Analyzing
110	      </Badge>
111	    );
112	  }
113	  if (status === "failed") {
114	    return (
115	      <Badge variant="outline" className="border-red-200/80 bg-red-50/50 text-red-700 text-xs">
116	        Failed
117	      </Badge>
118	    );
119	  }
120	  return <Badge variant="outline" className="text-xs capitalize">{status}</Badge>;
121	}
122	
123	// ── Component ───────────────────────────────────────────────────
124	
125	const Reports = () => {
126	  const navigate = useNavigate();
127	  const [search, setSearch] = useState("");
128	  const [statusFilter, setStatusFilter] = useState("all");
129	  const [scoreFilter, setScoreFilter] = useState("all");
130	  const [sortBy, setSortBy] = useState("newest");
131	
132	  const { data: scans = [], isLoading } = useScans();
133	  const deleteScan = useDeleteScan();
134	  const { profile } = useAuth();
135	  const { isMonitored, toggleMonitoring } = useMonitoring();
136	  const canMonitor = profile?.plan === "pro" || profile?.plan === "agency";
137	
138	  const hasActiveFilters = search || statusFilter !== "all" || scoreFilter !== "all";
139	
140	  const clearFilters = () => {
141	    setSearch("");
142	    setStatusFilter("all");
143	    setScoreFilter("all");
144	    setSortBy("newest");
145	  };
146	
147	  const filtered = useMemo(() => {
148	    let list = [...scans];
149	
150	    if (search) {
151	      const q = search.toLowerCase();
152	      list = list.filter(
153	        (s) =>
154	          s.url.toLowerCase().includes(q) ||
155	          (s.page_title?.toLowerCase().includes(q) ?? false)
156	      );
157	    }
158	
159	    if (statusFilter !== "all") {
160	      list = list.filter((s) => s.status === statusFilter);
161	    }
162	
163	    if (scoreFilter !== "all") {
164	      list = list.filter((s) => {
165	        if (s.overall_score === null) return false;
166	        if (scoreFilter === "poor") return s.overall_score < 40;
167	        if (scoreFilter === "average") return s.overall_score >= 40 && s.overall_score < 70;
168	        if (scoreFilter === "good") return s.overall_score >= 70;
169	        return true;
170	      });
171	    }
172	
173	    list.sort((a, b) => {
174	      if (sortBy === "newest") return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
175	      if (sortBy === "oldest") return new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
176	      if (sortBy === "score-high") return (b.overall_score ?? 0) - (a.overall_score ?? 0);
177	      if (sortBy === "score-low") return (a.overall_score ?? 0) - (b.overall_score ?? 0);
178	      return 0;
179	    });
180	
181	    return list;
182	  }, [scans, search, statusFilter, scoreFilter, sortBy]);
183	
184	  const handleDelete = (scanId: string, hostname: string) => {
185	    deleteScan.mutate(scanId, {
186	      onSuccess: () => toast.success(`Scan for ${hostname} deleted`),
187	      onError: () => toast.error("Failed to delete scan"),
188	    });
189	  };
190	
191	  return (
192	    <PageTransition>
193	      <div className="space-y-6">
194	        <PageHeader title="My Reports" description="View and manage your CRO audit reports">
195	          <Button asChild>
196	            <Link to="/scan">
197	              <ScanLine className="mr-2 h-4 w-4" />
198	              New Scan
199	            </Link>
200	          </Button>
201	        </PageHeader>
202	
203	        {/* Filter Bar */}
204	        <Card className="border-border/40 shadow-soft">
205	          <CardContent className="p-4">
206	            <div className="flex flex-wrap items-center gap-3">
207	              <div className="relative flex-1 min-w-[200px]">
208	                <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
209	                <Input
210	                  placeholder="Search by URL or page title..."
211	                  value={search}
212	                  onChange={(e) => setSearch(e.target.value)}
213	                  className="pl-9"
214	                />
215	              </div>
216	              <Select value={statusFilter} onValueChange={setStatusFilter}>
217	                <SelectTrigger className="w-36">
218	                  <SelectValue placeholder="Status" />
219	                </SelectTrigger>
220	                <SelectContent>
221	                  <SelectItem value="all">All Status</SelectItem>
222	                  <SelectItem value="completed">Completed</SelectItem>
223	                  <SelectItem value="analyzing">Analyzing</SelectItem>
224	                  <SelectItem value="failed">Failed</SelectItem>
225	                </SelectContent>
226	              </Select>
227	              <Select value={scoreFilter} onValueChange={setScoreFilter}>
228	                <SelectTrigger className="w-36">
229	                  <SelectValue placeholder="Score" />
230	                </SelectTrigger>
231	                <SelectContent>
232	                  <SelectItem value="all">All Scores</SelectItem>
233	                  <SelectItem value="poor">Poor (0-40)</SelectItem>
234	                  <SelectItem value="average">Average (40-70)</SelectItem>
235	                  <SelectItem value="good">Good (70+)</SelectItem>
236	                </SelectContent>
237	              </Select>
238	              <Select value={sortBy} onValueChange={setSortBy}>
239	                <SelectTrigger className="w-36">
240	                  <SelectValue placeholder="Sort" />
241	                </SelectTrigger>
242	                <SelectContent>
243	                  <SelectItem value="newest">Newest First</SelectItem>
244	                  <SelectItem value="oldest">Oldest First</SelectItem>
245	                  <SelectItem value="score-high">Score: High-Low</SelectItem>
246	                  <SelectItem value="score-low">Score: Low-High</SelectItem>
247	                </SelectContent>
248	              </Select>
249	              {hasActiveFilters && (
250	                <Button variant="ghost" size="sm" onClick={clearFilters} className="text-muted-foreground hover:text-foreground h-9">
251	                  <X className="mr-1.5 h-3.5 w-3.5" />
252	                  Clear Filters
253	                </Button>
254	              )}
255	            </div>
256	          </CardContent>
257	        </Card>
258	
259	        {/* Data Table */}
260	        {isLoading ? (
261	          <ReportTableSkeleton />
262	        ) : filtered.length > 0 ? (
263	          <Card className="border-border/40 shadow-soft overflow-hidden">
264	            <div className="overflow-x-auto scrollbar-thin">
265	              <Table>
266	                <TableHeader>
267	                  <TableRow className="hover:bg-transparent bg-muted/20">
268	                    <TableHead className="pl-5 min-w-[240px]">Website</TableHead>
269	                    <TableHead className="w-[100px]">Score</TableHead>
270	                    <TableHead className="w-[90px]">Issues</TableHead>
271	                    <TableHead className="w-[90px]">Type</TableHead>
272	                    <TableHead className="w-[100px]">Status</TableHead>
273	                    <TableHead className="w-[100px]">Date</TableHead>
274	                    <TableHead className="w-[50px] pr-5" />
275	                  </TableRow>
276	                </TableHeader>
277	                <TableBody>
278	                  {filtered.map((scan) => {
279	                    let hostname = scan.url;
280	                    try { hostname = new URL(scan.url).hostname; } catch { /* keep raw */ }
281	                    const displayHostname = hostname.replace("www.", "");
282	                    const faviconUrl = `https://www.google.com/s2/favicons?domain=${hostname}&sz=32`;
283	
284	                    return (
285	                      <TableRow
286	                        key={scan.id}
287	                        className="group cursor-pointer"
288	                        onClick={() => navigate(`/reports/${scan.id}`)}
289	                      >
290	                        {/* Website */}
291	                        <TableCell className="pl-5">
292	                          <div className="flex items-center gap-3">
293	                            <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-muted/40 overflow-hidden">
294	                              <img
295	                                src={faviconUrl}
296	                                alt=""
297	                                className="h-4 w-4"
298	                                onError={(e) => {
299	                                  e.currentTarget.style.display = "none";
300	                                  const parent = e.currentTarget.parentElement;
301	                                  if (parent && !parent.querySelector("svg")) {
302	                                    const fallback = document.createElement("span");
303	                                    fallback.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="text-muted-foreground"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>`;
304	                                    parent.appendChild(fallback);
305	                                  }
306	                                }}
307	                              />
308	                            </div>
309	                            <div className="min-w-0">
310	                              <p className="truncate text-sm font-medium text-foreground max-w-[200px]">
311	                                {scan.page_title ?? displayHostname}
312	                              </p>
313	                              <p className="truncate text-xs text-muted-foreground max-w-[200px]">
314	                                {displayHostname}
315	                              </p>
316	                            </div>
317	                          </div>
318	                        </TableCell>
319	
320	                        {/* Score */}
321	                        <TableCell>
322	                          {scan.overall_score !== null ? (
323	                            <div className="flex items-center gap-2">
324	                              <ScoreRing score={scan.overall_score} size={28} strokeWidth={3} showLabel={false} />
325	                              <span className={cn("text-sm font-semibold tabular-nums", getScoreColor(scan.overall_score))}>
326	                                {scan.overall_score}
327	                              </span>
328	                            </div>
329	                          ) : (
330	                            <span className="text-xs text-muted-foreground">--</span>
331	                          )}
332	                        </TableCell>
333	
334	                        {/* Issues */}
335	                        <TableCell>
336	                          <span className="text-sm text-muted-foreground tabular-nums">
337	                            {scan.issues_found}
338	                            {scan.critical_issues > 0 && (
339	                              <span className="ml-1 text-red-500 font-medium">
340	                                ({scan.critical_issues})
341	                              </span>
342	                            )}
343	                          </span>
344	                        </TableCell>
345	
346	                        {/* Type */}
347	                        <TableCell>
348	                          <Badge variant="outline" className="text-xs capitalize">
349	                            {scan.page_type}
350	                          </Badge>
351	                        </TableCell>
352	
353	                        {/* Status */}
354	                        <TableCell>
355	                          <div className="flex items-center gap-1.5">
356	                            {getStatusBadge(scan.status)}
357	                            {canMonitor && isMonitored(scan.url) && (
358	                              <Bell className="h-3 w-3 text-primary" />
359	                            )}
360	                          </div>
361	                        </TableCell>
362	
363	                        {/* Date */}
364	                        <TableCell className="text-sm text-muted-foreground">
365	                          {formatDate(scan.created_at)}
366	                        </TableCell>
367	
368	                        {/* Actions */}
369	                        <TableCell className="pr-5">
370	                          <DropdownMenu>
371	                            <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
372	                              <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
373	                                <MoreVertical className="h-4 w-4 text-muted-foreground" />
374	                              </Button>
375	                            </DropdownMenuTrigger>
376	                            <DropdownMenuContent align="end">
377	                              <DropdownMenuItem onClick={(e) => { e.stopPropagation(); navigate(`/reports/${scan.id}`); }}>
378	                                <Eye className="mr-2 h-3.5 w-3.5" /> View Report
379	                              </DropdownMenuItem>
380	                              <DropdownMenuItem onClick={(e) => { e.stopPropagation(); navigate(`/scan?url=${encodeURIComponent(scan.url)}&type=${scan.page_type}`); }}>
381	                                <RefreshCw className="mr-2 h-3.5 w-3.5" /> Re-scan
382	                              </DropdownMenuItem>
383	                              <DropdownMenuSeparator />
384	                              {canMonitor ? (
385	                                <DropdownMenuItem
386	                                  onClick={(e) => {
387	                                    e.stopPropagation();
388	                                    const wasMonitored = isMonitored(scan.url);
389	                                    toggleMonitoring(scan.url);
390	                                    toast.success(
391	                                      wasMonitored
392	                                        ? "Monitoring disabled for this URL"
393	                                        : "Monthly monitoring enabled — you'll get alerts when the score drops"
394	                                    );
395	                                  }}
396	                                >
397	                                  {isMonitored(scan.url) ? (
398	                                    <><BellOff className="mr-2 h-3.5 w-3.5 text-muted-foreground" />Stop Monitoring</>
399	                                  ) : (
400	                                    <><Bell className="mr-2 h-3.5 w-3.5" />Monitor Monthly</>
401	                                  )}
402	                                </DropdownMenuItem>
403	                              ) : (
404	                                <DropdownMenuItem disabled className="opacity-50">
405	                                  <Bell className="mr-2 h-3.5 w-3.5" />
406	                                  Monitor Monthly
407	                                  <Badge variant="outline" className="ml-auto text-2xs border-amber-200 bg-amber-50 text-amber-700">Pro</Badge>
408	                                </DropdownMenuItem>
409	                              )}
410	                              <DropdownMenuSeparator />
411	                              <DropdownMenuItem
412	                                className="text-red-600"
413	                                onClick={(e) => {
414	                                  e.stopPropagation();
415	                                  handleDelete(scan.id, displayHostname);
416	                                }}
417	                              >
418	                                <Trash2 className="mr-2 h-3.5 w-3.5" /> Delete
419	                              </DropdownMenuItem>
420	                            </DropdownMenuContent>
421	                          </DropdownMenu>
422	                        </TableCell>
423	                      </TableRow>
424	                    );
425	                  })}
426	                </TableBody>
427	              </Table>
428	            </div>
429	
430	            {/* Results count */}
431	            <div className="border-t border-border/30 bg-muted/10 px-5 py-3">
432	              <p className="text-xs text-muted-foreground">
433	                Showing {filtered.length} of {scans.length} report{scans.length !== 1 ? "s" : ""}
434	              </p>
435	            </div>
436	          </Card>
437	        ) : (
438	          <EmptyState
439	            icon={ScanLine}
440	            title="No reports found"
441	            description={
442	              hasActiveFilters
443	                ? "Try adjusting your filters to find what you're looking for."
444	                : "Run your first CRO audit to see results here."
445	            }
446	            actionLabel="Start New Scan"
447	            actionHref="/scan"
448	          />
449	        )}
450	      </div>
451	    </PageTransition>
452	  );
453	};
454	
455	export default Reports;
