1	import { useState } from "react";
2	import {
3	  BarChart2,
4	  Flame,
5	  MousePointer2,
6	  Search,
7	  CheckCircle2,
8	  Circle,
9	  Loader2,
10	  type LucideIcon,
11	} from "lucide-react";
12	import { toast } from "sonner";
