36	// ── Integration config types ───────────────────────────────────
37	
38	interface IntegrationConfig {
39	  id: IntegrationProvider;
40	  name: string;
41	  icon: LucideIcon;
42	  color: string;
43	  bg: string;
44	  description: string;
45	  inputLabel: string;
46	  inputPlaceholder: string;
47	  inputHint: string;
48	  benefits: string[];
49	}
50	
51	// ── Static integration configs ─────────────────────────────────
52	
53	const INTEGRATIONS: IntegrationConfig[] = [
54	  {
55	    id: "google_analytics",
56	    name: "Google Analytics 4",
57	    icon: BarChart2,
58	    color: "text-orange-500",
59	    bg: "bg-orange-50",
60	    description:
61	      "Connect your GA4 property to enrich CRO recommendations with traffic and behavior data.",
62	    inputLabel: "Measurement ID",
