65	      "Find this in GA4 → Admin → Data Streams → your stream → Measurement ID",
66	    benefits: [
67	      "Bounce rate context for each page",
68	      "Traffic source analysis",
69	      "Session duration insights",
70	    ],
71	  },
72	  {
73	    id: "hotjar",
74	    name: "Hotjar",
75	    icon: Flame,
76	    color: "text-red-500",
77	    bg: "bg-red-50",
78	    description:
79	      "Import heatmap and session recording data for deeper conversion insights.",
80	    inputLabel: "Site ID",
81	    inputPlaceholder: "1234567",
82	    inputHint:
83	      "Find your Site ID in Hotjar → Settings → Sites & Organizations",
84	    benefits: [
85	      "Heatmap analysis integration",
86	      "Rage click detection",
87	      "Scroll depth data",
88	    ],
89	  },
90	  {
91	    id: "clarity",
92	    name: "Microsoft Clarity",
93	    icon: MousePointer2,
94	    color: "text-blue-500",
95	    bg: "bg-blue-50",
96	    description:
97	      "Free heatmaps and session recordings to complement your CRO audits.",
98	    inputLabel: "Project ID",
99	    inputPlaceholder: "abc1234xyz",
100	    inputHint: "Find your Project ID in Clarity → Settings → your project",
101	    benefits: [
102	      "Free session recordings",
103	      "Click heatmaps",
104	      "Dead click detection",
105	    ],
106	  },
107	  {
