import React from "react";
import { AlertTriangle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

interface ErrorStateProps {
  title: string;
  description: string;
  onRetry: () => void;
  className?: string;
}

export const ErrorState = React.forwardRef<HTMLDivElement, ErrorStateProps>(
  function ErrorState({ title, description, onRetry, className }, ref) {
    return (
      <div
        ref={ref}
        className={cn(
          "flex flex-col items-center justify-center py-16 text-center",
          className
        )}
      >
        <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-2xl border border-red-200/60 bg-red-50/60">
          <AlertTriangle className="h-7 w-7 text-red-500" />
        </div>
        <h3 className="text-lg font-semibold text-foreground">{title}</h3>
        <p className="mt-1.5 max-w-sm text-sm text-muted-foreground">
          {description}
        </p>
        <Button className="mt-5" size="sm" onClick={onRetry}>
          Try Again
        </Button>
      </div>
    );
  }
);

